function custItems(){ settings.custItems=settings.custItems||[]; settings.custStock=settings.custStock||{}; settings.custItems.forEach(c=>{ if(!settings.custStock[c.name]) settings.custStock[c.name]={in:0,used:0,cost:0} }); return settings.custItems }
function custCardsRender(){
  const host=document.getElementById('cardReset'); if(!host) return;
  document.querySelectorAll('[data-cust]').forEach(c=>{ if(!custItems().some(x=>'cardC_'+x.name===c.id)) c.remove() });
  custItems().forEach(ci=>{
    let c=document.getElementById('cardC_'+ci.name);
    if(!c){ c=document.createElement('div'); c.className='card'; c.id='cardC_'+ci.name; c.dataset.cust=ci.name;
      c.innerHTML=`<h3></h3><div class="totals"><div class="trow"><span>المشترى</span><span class="cc-in"></span></div><div class="trow"><span>المصروف</span><span class="cc-used"></span></div><div class="trow"><span>قيمة المتبقي</span><span class="cc-val"></span></div><div class="trow big"><span>المتبقي</span><span class="cc-left"></span></div></div>
        <div class="fcount"><label>جرد: الموجود هسه</label><div class="fcount-row"><input class="cc-c" type="number" inputmode="decimal" min="0" step="0.5"><button class="btn-dark cc-b" type="button">ثبّت</button></div></div>`;
      host.parentNode.insertBefore(c,host);
      c.querySelector('.cc-b').addEventListener('click',()=>{ const v=parseFloat(c.querySelector('.cc-c').value); if(!(v>=0)){ toast('اكتب الكمية'); return }
        const s=settings.custStock[ci.name]; s.used=Math.max(0,Math.round(((s.in||0)-v)*100)/100); if(v>(s.in||0)) s.in=v;
        c.querySelector('.cc-c').value=''; saveAll(); custCardsRender(); toast('انحفظ: '+ci.name) });
    }
    const s=settings.custStock[ci.name], left=Math.max(0,Math.round(((s.in||0)-(s.used||0))*100)/100), u=' '+(ci.unit||'');
    c.querySelector('h3').textContent=ci.name;
    c.querySelector('.cc-in').textContent=fmt(s.in||0)+u; c.querySelector('.cc-used').textContent=fmt(s.used||0)+u;
    c.querySelector('.cc-val').textContent=fmt(Math.round(left*(s.cost||0)))+' د.ع'; c.querySelector('.cc-left').textContent=fmt(left)+u;
  });
  try{ initBoard() }catch(_){}
}
function custChipsRender(){
  const ch=document.getElementById('buyChips'); if(!ch) return;
  ch.querySelectorAll('[data-k^="cust:"],.chip-add').forEach(b=>b.remove());
  custItems().forEach(ci=>{ const b=document.createElement('button'); b.dataset.k='cust:'+ci.name; b.textContent=ci.name;
    b.addEventListener('click',()=>{ document.getElementById('buyName').value=ci.name; buyDetect(); document.getElementById('buyQty').focus() }); ch.appendChild(b) });
  const a=document.createElement('button'); a.className='chip-add'; a.type='button'; a.textContent='+ صنف جديد / تعديل'; a.addEventListener('click',custEdit); ch.appendChild(a);
}
function custEdit(){
  const ov=document.createElement('div'); ov.className='ov'; let list=custItems().map(x=>({name:x.name,unit:x.unit||'',old:x.name}));
  const draw=()=>{ ov.innerHTML=`<div class="dlg" role="dialog" aria-modal="true"><div class="dlg-t">أصناف المسواك الإضافية</div>
    <p class="note" style="margin-bottom:8px">كل صنف تضيفه يطلع بالمسواك، وينسوي اله مخزن بحده بصفحة المخزن.</p>
    <div class="bw-list">${list.map((n,i)=>`<div class="fcount-row"><input data-n="${i}" value="${esc(n.name)}" aria-label="الاسم"><input data-u="${i}" value="${esc(n.unit)}" placeholder="الوحدة" style="max-width:90px" aria-label="الوحدة"><button class="btn-ghost" data-del="${i}" type="button">احذف</button></div>`).join('')||'<p class="note">بعد ما ضايف شي.</p>'}</div>
    <div class="fcount-row" style="margin-top:10px"><input id="ciNew" placeholder="اسم الصنف، مثلاً بصل"><input id="ciUnit" placeholder="كغم" style="max-width:90px"><button class="btn-dark" id="ciAdd" type="button">ضيف</button></div>
    <div class="dlg-act"><button class="btn-main" id="ciSave">احفظ</button><button class="btn-ghost" id="ciX">إلغاء</button></div></div>`;
    const read=()=>{ ov.querySelectorAll('[data-n]').forEach(x=>{ const i=+x.dataset.n; list[i].name=x.value.trim(); list[i].unit=ov.querySelector('[data-u="'+i+'"]').value.trim() }) };
    ov.querySelectorAll('[data-del]').forEach(b=>b.addEventListener('click',()=>{ read(); list.splice(+b.dataset.del,1); draw() }));
    ov.querySelector('#ciAdd').addEventListener('click',()=>{ read(); const v=ov.querySelector('#ciNew').value.trim(); if(!v){ toast('اكتب اسم الصنف'); return } if(list.some(x=>x.name===v)){ toast('موجود'); return } list.push({name:v,unit:ov.querySelector('#ciUnit').value.trim()||'كغم',old:null}); draw() });
    ov.querySelector('#ciX').addEventListener('click',()=>ov.remove());
    ov.querySelector('#ciSave').addEventListener('click',()=>{ read(); const S=settings.custStock||{}, NS={};
      list=list.filter(x=>x.name); list.forEach(x=>{ NS[x.name]=(x.old&&S[x.old])||S[x.name]||{in:0,used:0,cost:0} });
      settings.custItems=list.map(x=>({name:x.name,unit:x.unit||'كغم'})); settings.custStock=NS;
      saveAll(); custChipsRender(); custCardsRender(); try{ buyDetect() }catch(_){} ov.remove(); toast('انحفظت الأصناف') });
  };
  draw(); document.body.appendChild(ov);
}
